/* @lc app=leetcode id=3714 lang=kotlin */ class Solution { fun two(s: String, x: Char, y: Char, z: Char): Int = HashMap<Int, Int>().also { it[0] = 0 }.let { m -> s.indices.fold(0 to 0) { (d, best), i -> if (s[i] == z) m.clear().let { m.put(0, i + 1) }.let { 0 to best } else (d + (if (s[i] == x) 1 else -1)).let { d2 -> if (m.containsKey(d2)) d2 to maxOf(best, i + 1 - m[d2]!!) else m.put(d2, i + 1).let { d2 to best } } }.second } fun longestBalanced(s: String): Int = maxOf((s.indices.filter { it == 0 || s[it] != s[it - 1] } + s.length).zipWithNext { a, b -> b - a }.max(), two(s, 'a', 'b', 'c'), two(s, 'a', 'c', 'b'), two(s, 'b', 'c', 'a'), HashMap<Pair<Int, Int>, Int>().also { it[0 to 0] = 0 }.let { m -> s.indices.fold(Triple(0, 0, 0) to 0) { (cnt, best), i -> Triple(cnt.first + (if (s[i] == 'a') 1 else 0), cnt.second + (if (s[i] == 'b') 1 else 0), cnt.third + (if (s[i] == 'c') 1 else 0)).let { c -> (c.first - c.second to c.first - c.third).let { k -> if (m.containsKey(k)) c to maxOf(best, i + 1 - m[k]!!) else m.put(k, i + 1).let { c to best } } } }.second }) }